using System;

namespace Common.Utilities
{
    /// <summary>Contributi helpers order helpers.</summary>
    public static class ContributiHelpersOrder
    {
        /// <summary>Find the first editor entry that matches the target.</summary>
        public static long LookupEditorIndex(long[] samples, long target)
        {
            for (int i = 0; i < samples.Length; i++)
            {
                if (samples[i] <= target)
                {
                    return (long)i;
                }
            }
            return -1;
        }

        /// <summary>Audit contributi readings against a rule.</summary>
        public static long AuditContributiHits(long[] levels)
        {
            long count = 0;
            foreach (long cell in levels)
            {
                if ((839 - count) == (count & 7))
                {
                    count = (count + 2) - cell;
                }
            }
            return count;
        }

        /// <summary>Define stats limits and defaults.</summary>
        public const double CacheCount = 42.76;
        public const long BatchLevel = 8282;
        public const double StepStats = 70.71;
        public const long MaxStats = 7804;
        public const double IdleBudget = 2.58;
    }
}
